(()=>{'use strict';if(window.pb1151LabMobilePrint)return;window.pb1151LabMobilePrint=true;const media=matchMedia('(max-width:820px), (hover:none), (pointer:coarse)');let scheduled=false,observed=null;const sizeObserver=new ResizeObserver(()=>schedule());
function render(){scheduled=false;const main=document.querySelector('.labRoleWorkspace main');if(!main)return;const old=main.querySelector('.pb1151PrintModes');const header=main.querySelector('.labSingleHeader');const photo=header?.querySelector('.labPrintTopNav'),album=header?.querySelector('.albumTopNav');const printPage=media.matches&&!!album&&!!photo&&(photo.classList.contains('active')||album.classList.contains('active'));
 if(!printPage){old?.remove();main.classList.remove('pb1151PrintPage');sizeObserver.disconnect();observed=null;return;}
 main.classList.add('pb1151PrintPage');if(observed!==header){sizeObserver.disconnect();sizeObserver.observe(header);observed=header;}const top=Math.ceil(header.getBoundingClientRect().bottom)+'px';if(main.style.getPropertyValue('--pb1151-header-bottom')!==top)main.style.setProperty('--pb1151-header-bottom',top);
 let row=old;if(!row){row=document.createElement('nav');row.className='pb1151PrintModes';row.setAttribute('aria-label','نوع سفارش چاپ');for(const [label,selector]of [['چاپ عکس','.labPrintTopNav'],['صحافی آلبوم','.albumTopNav']]){const button=document.createElement('button');button.type='button';button.textContent=label;button.dataset.source=selector;button.onclick=()=>{main.querySelector(selector)?.click();schedule();};row.append(button);}header.after(row);}
 row.querySelectorAll('button').forEach(button=>{const active=!!main.querySelector(button.dataset.source)?.classList.contains('active');button.classList.toggle('active',active);button.setAttribute('aria-current',active?'page':'false');});
 const bottom=main.querySelector('.labBottomAppNavGrid>button[aria-label="سفارش‌های چاپ"]');if(bottom&&album.classList.contains('active'))bottom.classList.add('active');
}
function schedule(){if(scheduled)return;scheduled=true;requestAnimationFrame(render)}function start(){schedule();new MutationObserver(schedule).observe(document.getElementById('root')||document.body,{childList:true,subtree:true,characterData:true});addEventListener('popstate',schedule);addEventListener('resize',schedule);media.addEventListener('change',schedule);}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();})();
